const input = $input.first().json;
const secret = (input.headers || {})['x-ray-secret'];
if (secret !== 'SET_MARKETING_WEBHOOK_SECRET') throw new Error('Unauthorized');
const b = input.body || {};
const manual = b.mode === 'manual';
const validId = v => /^[0-9a-f-]{36}$/i.test(String(v || ''));
const folderOk = /^[A-Za-z0-9_-]{10,200}$/.test(String(b.drive_folder_id || ''));
const umk = Number(b.umk);
const gaji = (b.gaji_pokok === undefined || b.gaji_pokok === null || b.gaji_pokok === '') ? umk : Number(b.gaji_pokok);
const counts = manual ? ['security','cleaning','pramubakti','driver'].map(k => Number(b.jumlah_personel?.[k])) : [1,1,1,1];
const recipient = manual ? String(b.ditujukan_kepada || '').trim().replace(/^Yth\.?\s*/i,'').slice(0,180) : 'Pimpinan';
const isoDate = String(b.tanggal_surat || '');
const manualDate = /^\d{4}-\d{2}-\d{2}$/.test(isoDate) ? new Date(`${isoDate}T00:00:00+07:00`) : new Date(NaN);
const localParts = Number.isFinite(manualDate.getTime()) ? new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(manualDate) : [];
const localPart = type => localParts.find(p => p.type === type)?.value || '';
const dateOk = `${localPart('year')}-${localPart('month')}-${localPart('day')}` === isoDate;
if (!validId(b.offer_id) || (!manual && !validId(b.lead_id)) || !folderOk ||
    !String(b.nama_target || '').trim() || !Number.isSafeInteger(umk) || umk < 1 || umk > 1000000000 || !Number.isSafeInteger(gaji) || gaji < 1 || gaji > 1000000000 ||
    (manual && (!recipient || !String(b.alamat || '').trim() || !String(b.kabupaten_kota || '').trim() ||
      !String(b.provinsi || '').trim() || !Number.isFinite(manualDate.getTime()) ||
      !dateOk ||
      counts.some(n => !Number.isSafeInteger(n) || n < 0 || n > 5000) || counts.every(n => n === 0))))
  throw new Error('Data penawaran tidak valid');
const now = manual ? manualDate : new Date();
const dateParts = new Intl.DateTimeFormat('id-ID', {timeZone:'Asia/Jakarta',year:'numeric',month:'long',day:'numeric'}).formatToParts(now);
const part = type => dateParts.find(p => p.type === type)?.value || '';
const monthNumber = Number(new Intl.DateTimeFormat('en-US', {timeZone:'Asia/Jakarta',month:'numeric'}).format(now));
return [{json:{offer_id:String(b.offer_id),lead_id:manual ? null : String(b.lead_id),mode:manual ? 'manual' : 'lead',
  drive_folder_id:String(b.drive_folder_id),nama_target:String(b.nama_target).trim().slice(0,180),
  ditujukan_kepada:recipient, jumlah_personel:counts,
  alamat:String(b.alamat || '').slice(0,500),kecamatan:String(b.kecamatan || '').slice(0,100),
  kabupaten_kota:String(b.kabupaten_kota || '').slice(0,100),provinsi:String(b.provinsi || '').slice(0,100),
  umk,gaji_pokok:gaji,tahun:Number(part('year')),tanggal:`${part('day')} ${part('month')} ${part('year')}`,
  bulanRomawi:['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'][monthNumber-1]}}];

const meta = $('Validasi Penawaran Web').first().json;
const counter = $input.first().json;
const nomorTerakhir = Number(counter.nomor_terakhir || 0);
if (!Number.isSafeInteger(nomorTerakhir) || nomorTerakhir < 0 || String(counter.tahun) !== String(meta.tahun))
  throw new Error('Counter nomor surat tahun ini tidak valid');
const nomorUrutBaru = nomorTerakhir + 1;
return [{json:{...meta,nomorUrutBaru,nomorSurat:`${nomorUrutBaru}/202/RAYMP/${meta.bulanRomawi}/${meta.tahun}`,
  namaClient:meta.nama_target,alamat1:meta.alamat,
  alamat2:[meta.kecamatan,meta.kabupaten_kota,meta.provinsi].filter(Boolean).join(', '),
  kotaClient:meta.kabupaten_kota}}];
